<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { createProjectApi, getProjectId, loadSummaryPages, pathId } from '../api.js';
import { Button, ErrorBox, Loading, Modal, Notice } from '../ui/index.js';
import EnvironmentVariableValue from '../api-management/EnvironmentVariableValue.vue';
import { useProjectEnvironments } from './environments.js';
import { collectionEnvironments, resolveCollectionEnvironment, validateCollectionEnvironment, publishEnvironmentReceipt } from '../api-management/collection-environments.js';
import { loadEnvironmentManagement, rememberEnvironmentManagement } from './view-state.js';
const props=defineProps({readOnly:Boolean,collectionId:String});
const api=createProjectApi(),projectId=getProjectId(),parents=useProjectEnvironments(),remembered=loadEnvironmentManagement(projectId);
const collections=ref([]),collection=ref(null),loading=ref(false),saving=ref(false),error=ref(null),draft=ref(null),baseline=ref('null'),pending=ref(null),deleting=ref(false);
let sequence=0;
const rows=computed(()=>collectionEnvironments(collection.value,parents.state.items));
const dirty=computed(()=>JSON.stringify(draft.value)!==baseline.value);
const effective=computed(()=>{try{return {value:resolveCollectionEnvironment(draft.value,parents.state.items)}}catch(error){return {error}}});
function select(row){draft.value=row?JSON.parse(JSON.stringify(row)):null;baseline.value=JSON.stringify(draft.value);remember();}
function remember(){rememberEnvironmentManagement(projectId,{section:'collection',collectionId:collection.value?.id||'',environmentId:draft.value?.id||''});}
function guard(action){if(saving.value)return;if(dirty.value)pending.value=action;else action();}
async function loadCollection(id){const token=++sequence;loading.value=true;error.value=null;try{const item=await api(`/api-collections/${pathId(id)}`);if(token!==sequence)return;collection.value=item;select(rows.value.find(row=>row.id===remembered.environmentId)||null);}catch(reason){if(token===sequence)error.value=reason;}finally{if(token===sequence)loading.value=false;}}
async function load(){loading.value=true;try{const [listed]=await Promise.all([loadSummaryPages(api,'/api-collections'),parents.load()]);collections.value=listed.items||[];const id=props.collectionId||remembered.collectionId;if(collections.value.some(item=>item.id===id))await loadCollection(id);else if(collections.value.length)await loadCollection(collections.value[0].id);}catch(reason){error.value=reason;}finally{loading.value=false;}}
function changeCollection(event){const id=event.target.value;event.target.value=collection.value?.id||'';guard(()=>loadCollection(id));}
function create(){guard(()=>select({name:'',variables:[]}));}
async function save(){if(props.readOnly||saving.value||!draft.value)return;saving.value=true;error.value=null;try{validateCollectionEnvironment(draft.value);const id=draft.value.id;const {available,effective,collection_revision,...authored}=draft.value;const result=await api(`/api-collections/${pathId(collection.value.id)}/collection-environments${id?`/${pathId(id)}`:''}`,{method:id?'PUT':'POST',body:{...authored,revision:collection.value.revision}});collection.value=result.collection;publishEnvironmentReceipt(projectId,result.collection);select(result.environment);return result;}catch(reason){error.value=reason.status===409?new Error('集合已被其他页面更新。草稿已保留，请重新读取集合后合并修改。'):reason;throw reason;}finally{saving.value=false;}}
async function remove(){if(props.readOnly||!draft.value?.id)return;saving.value=true;error.value=null;try{const result=await api(`/api-collections/${pathId(collection.value.id)}/collection-environments/${pathId(draft.value.id)}`,{method:'DELETE',body:{revision:collection.value.revision}});collection.value=result.collection;publishEnvironmentReceipt(projectId,result.collection);select(null);deleting.value=false;}catch(reason){error.value=reason;}finally{saving.value=false;}}
async function saveAndContinue(){try{await save();const action=pending.value;pending.value=null;action?.();}catch{/* Keep the draft and pending choice visible. */}}
function discardAndContinue(){const action=pending.value;pending.value=null;select(rows.value.find(row=>row.id===draft.value?.id)||null);action?.();}
function setParent(value){if(value)draft.value.parent_environment_id=value;else delete draft.value.parent_environment_id;}
function setOverride(value){if(value)draft.value.base_host='';else delete draft.value.base_host;}
watch(()=>props.collectionId,id=>{if(id&&id!==collection.value?.id)guard(()=>loadCollection(id));});
onMounted(load);
defineExpose({hasUnsavedChanges:()=>dirty.value,isBusy:()=>saving.value,saveChanges:save,discardChanges:()=>select(rows.value.find(row=>row.id===draft.value?.id)||null)});
</script>
<template>
 <section class="collection-environments" aria-label="集合环境管理">
  <ErrorBox :error="error"/><Notice v-if="readOnly">项目已归档，集合环境只读。</Notice>
  <div class="collection-toolbar"><label>接口集合<select class="ui-select" aria-label="环境所属集合" :value="collection?.id||''" :disabled="saving||loading" @change="changeCollection"><option value="" disabled>请选择接口集合</option><option v-for="item in collections" :key="item.id" :value="item.id">{{item.name}}</option></select></label><Button :disabled="!collection||readOnly||saving" @click="create">新增集合环境</Button><Button :disabled="!collection||saving" @click="guard(()=>loadCollection(collection.id))">重新读取集合</Button></div>
  <Loading v-if="loading"/>
  <p v-else-if="!collection">请先在接口管理创建集合。</p>
  <div v-else class="collection-environment-layout">
   <aside aria-label="集合环境列表"><button v-for="row in rows" :key="row.id" :class="{active:draft?.id===row.id}" @click="guard(()=>select(row))"><strong>{{row.name}}</strong><small>{{row.parent_environment_id ? parents.state.items.find(item=>item.id===row.parent_environment_id)?.name || '父环境已失效' : '独立环境'}}</small></button><p v-if="!rows.length">请先创建集合环境</p></aside>
   <form v-if="draft" class="collection-environment-form" @submit.prevent="save().catch(()=>{})"><p>所属集合：{{collection.name}} · 版本 {{collection.revision}}</p><fieldset :disabled="readOnly||saving"><label>环境名称<input v-model="draft.name" aria-label="集合环境名称" maxlength="200"/></label><label>父项目环境<select class="ui-select" aria-label="父项目环境" :value="draft.parent_environment_id||''" @change="setParent($event.target.value)"><option value="">独立环境</option><option v-if="draft.parent_environment_id&&!parents.state.items.some(item=>item.id===draft.parent_environment_id)" :value="draft.parent_environment_id" disabled>原父环境已失效</option><option v-for="parent in parents.state.items" :key="parent.id" :value="parent.id">{{parent.name}} · 版本 {{parent.revision}}</option></select></label><label v-if="draft.parent_environment_id" class="override-toggle"><input type="checkbox" :checked="Object.hasOwn(draft,'base_host')" @change="setOverride($event.target.checked)"/>自定义基础地址</label><label v-if="!draft.parent_environment_id||Object.hasOwn(draft,'base_host')">基础地址<input :value="draft.base_host||''" @input="draft.base_host=$event.target.value" aria-label="集合环境基础地址" placeholder="https://example.com/base"/></label><p v-else class="muted">继承地址：{{parents.state.items.find(item=>item.id===draft.parent_environment_id)?.base_host||'不可用'}}</p><div class="variable-heading"><h3>自定义变量与覆盖</h3><Button type="button" @click="draft.variables.push({name:'',value:''})">添加变量</Button></div><div class="collection-variable" v-for="(row,index) in draft.variables" :key="index"><input v-model="row.name" :aria-label="`集合变量名 ${index+1}`" placeholder="变量名"/><EnvironmentVariableValue v-model="row.value" :value-label="`集合变量值 ${index+1}`" :rule-label="`集合变量生成方式 ${index+1}`" :length-label="`集合变量生成长度 ${index+1}`" :disabled="readOnly||saving"/><Button type="button" :aria-label="`删除集合变量 ${index+1}`" @click="draft.variables.splice(index,1)">删除</Button></div><p class="muted">删除覆盖项后恢复继承；空字符串是有效的覆盖值。</p></fieldset><div class="collection-form-actions"><Button type="submit" variant="primary" :disabled="readOnly||saving||!dirty">{{saving?'正在保存…':'保存集合环境'}}</Button><Button v-if="draft.id" type="button" variant="danger" :disabled="readOnly||saving" @click="deleting=true">删除集合环境</Button></div><details open><summary>最终生效配置</summary><ErrorBox :error="effective.error"/><template v-if="effective.value"><p>基础地址：{{effective.value.base_host}}</p><table><thead><tr><th>变量</th><th>值</th><th>来源</th></tr></thead><tbody><tr v-for="row in effective.value.variables" :key="row.name"><td>{{row.name}}</td><td>{{/token|secret|password|cookie|authorization/i.test(row.name)?'••••••':row.value}}</td><td>{{draft.variables.some(item=>item.name===row.name)?'集合自定义':'父项目环境'}}</td></tr></tbody></table></template></details></form>
   <p v-else>选择一个集合环境，或新增环境。</p>
  </div>
  <Modal v-if="pending" title="处理未保存的环境修改" @close="pending=null"><p>当前集合环境有未保存修改。</p><ErrorBox :error="error"/><template #footer><Button :disabled="saving" @click="pending=null">取消切换</Button><Button :disabled="saving" @click="discardAndContinue">放弃修改并切换</Button><Button variant="primary" :disabled="saving||readOnly" @click="saveAndContinue">保存后切换</Button></template></Modal>
  <Modal v-if="deleting" title="删除集合环境" @close="!saving&&(deleting=false)"><p>删除「{{draft.name}}」后不再用于新的调试。已发布流程保留其历史版本。</p><template #footer><Button :disabled="saving" @click="deleting=false">取消</Button><Button variant="danger" :disabled="saving" @click="remove">确认删除</Button></template></Modal>
 </section>
</template>
<style scoped>
.collection-environments{display:flex;flex-direction:column;gap:18px;min-height:0;min-width:0;flex:1}.collection-toolbar{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.collection-toolbar label{display:grid;gap:7px;min-width:min(100%,280px)}.collection-environment-layout{display:grid;grid-template-columns:240px minmax(0,1fr);flex:1;min-height:360px;overflow:hidden;gap:24px}.collection-environment-layout aside{overflow:auto;border-right:1px solid var(--border);padding-right:16px}.collection-environment-layout aside button{display:grid;gap:8px;width:100%;padding:14px;border:0;border-radius:8px;background:transparent;color:var(--text);text-align:left;cursor:pointer}.collection-environment-layout aside button.active{background:var(--accent-soft);color:var(--accent)}small,.muted{color:var(--muted);font-size:12px}.collection-environment-form{overflow:auto;min-width:0;display:flex;flex-direction:column;gap:18px;padding:0 4px 16px}.collection-environment-form fieldset{border:0;padding:0;margin:0;display:grid;gap:16px;min-width:0}.collection-environment-form label{display:grid;gap:7px;font-size:13px}.collection-environment-form input:not([type=checkbox]){padding:10px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text);min-width:0;width:100%;box-sizing:border-box}.collection-environment-form .override-toggle{display:flex;align-items:center}.collection-variable{display:grid;grid-template-columns:minmax(100px,1fr) minmax(150px,2fr) auto;gap:8px}.variable-heading,.collection-form-actions{display:flex;justify-content:space-between;align-items:center;gap:12px}.variable-heading h3{font-size:14px}.collection-form-actions{justify-content:flex-start}.collection-environment-form table{width:100%;text-align:left;border-collapse:collapse;font-size:12px;table-layout:fixed}.collection-environment-form td,.collection-environment-form th{padding:10px;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.collection-environment-form details p{overflow-wrap:anywhere}@media(max-width:760px){.collection-environment-layout{grid-template-columns:minmax(0,1fr);overflow:visible}.collection-environment-layout aside{border-right:0;border-bottom:1px solid var(--border);max-height:220px;padding:0}.collection-environment-form{overflow:visible}.collection-variable{grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto}}
</style>
